function [Sp0_imj,Sp0_ipj,Sm0_ijm,Sm0_ijp] = fluxes_dke_jd(Dpp_imj,Dpp_ipj,Dpm_imj,Dpm_ipj,Fp_imj,Fp_ipj,...    Dmm_ijm,Dmm_ijp,Dmp_ijm,Dmp_ijp,Fm_ijm,Fm_ijp,...    f0_ij,pn,pnm,pnp,lmmhu2,lmmhu2m,lmmhu2p,dpnm,dpnp,...    dmhum,dmhup,...    deltap_imj,deltap_ipj,deltam_ijm,deltam_ijp);% by J. Decker. 12/03/02%% modified J.D. 07/02/03npn = size(f0_ij,1);nmhu = size(f0_ij,2);f0_immj = zeros(size(f0_ij));f0_imjpp = zeros(size(f0_ij));f0_imjmm = zeros(size(f0_ij));f0_ippj = zeros(size(f0_ij));f0_ipjpp = zeros(size(f0_ij));f0_ipjmm = zeros(size(f0_ij));f0_ijmm = zeros(size(f0_ij));f0_immjp = zeros(size(f0_ij));f0_immjm = zeros(size(f0_ij));f0_ijpp = zeros(size(f0_ij));f0_ippjm = zeros(size(f0_ij));f0_ippjp = zeros(size(f0_ij));%f0_immj(2:npn,:,:,:) = f0_ij(1:npn-1,:,:,:);f0_immj(1,:,:,:) = f0_ij(1,:,:,:); % since df/dp(p==0) = 0;f0_ippj(1:npn-1,:,:,:) = f0_ij(2:npn,:,:,:);f0_ippj(npn,:,:,:) = 0; % point outside pmax;f0_imj = (1 - deltap_imj).*f0_ij + deltap_imj.*f0_immj;f0_ipj = (1 - deltap_ipj).*f0_ippj + deltap_ipj.*f0_ij;f0_imjpp(:,1:nmhu-1,:,:) = f0_imj(:,2:nmhu,:,:);f0_imjpp(:,nmhu,:,:) = f0_imj(:,nmhu,:,:); % since df/dm(m==1) = 0;f0_imjmm(:,2:nmhu,:,:) = f0_imj(:,1:nmhu-1,:,:);f0_imjmm(:,1,:,:) = f0_imj(:,1,:,:); % since df/dm(m==-1) = 0;    f0_ipjpp(:,1:nmhu-1,:,:) = f0_ipj(:,2:nmhu,:,:);f0_ipjpp(:,nmhu,:,:) = f0_ipj(:,nmhu,:,:); % since df/dm(m==1) = 0;f0_ipjmm(:,2:nmhu,:,:) = f0_ipj(:,1:nmhu-1,:,:);f0_ipjmm(:,1,:,:) = f0_ipj(:,1,:,:); % since df/dm(m==-1) = 0;%%f0_ijmm(:,2:nmhu,:,:) = f0_ij(:,1:nmhu-1,:,:);f0_ijmm(:,1,:,:) = f0_ij(:,1,:,:); % since df/dm(m==-1) = 0;f0_ijpp(:,1:nmhu-1,:,:) = f0_ij(:,2:nmhu,:,:);f0_ijpp(:,nmhu,:,:) = f0_ij(:,nmhu,:,:); % since df/dm(m==1) = 0;f0_ijm = (1 - deltam_ijm).*f0_ij + deltam_ijm.*f0_ijmm;f0_ijp = (1 - deltam_ijp).*f0_ippj + deltam_ijp.*f0_ij;f0_immjm(2:npn,:,:,:) = f0_ijm(1:npn-1,:,:,:);f0_immjm(1,:,:,:) = f0_ijm(1,:,:,:); % since df/dp(p==0) = 0;f0_ippjm(1:npn-1,:,:,:) = f0_ijm(2:npn,:,:,:);f0_ippjm(npn,:,:,:) = 0; % point outside pmax;f0_immjp(2:npn,:,:,:) = f0_ijp(1:npn-1,:,:,:);f0_immjp(1,:,:,:) = f0_ijp(1,:,:,:); % since df/dp(p==0) = 0;f0_ippjp(1:npn-1,:,:,:) = f0_ijp(2:npn,:,:,:);f0_ippjp(npn,:,:,:) = 0; % point outside pmax;%%    Sp0_imj = Dpp_imj.*(f0_immj - f0_ij)./dpnm...        + Dpm_imj.*sqrt(lmmhu2)./pnm./(dmhum + dmhup).*(f0_imjpp-f0_imjmm)...        + Fp_imj.*f0_imj;Sp0_ipj = Dpp_ipj.*(f0_ij - f0_ippj)./dpnp...        + Dpm_ipj.*sqrt(lmmhu2)./pnp./(dmhum + dmhup).*(f0_ipjpp-f0_ipjmm)...        + Fp_ipj.*f0_ipj;Sm0_ijm = Dmm_ijm.*(f0_ij - f0_ijmm).*sqrt(lmmhu2m)./pn./dmhum...        - Dmp_ijm./(dpnm + dpnp).*(f0_ippjm-f0_immjm)...        + Fm_ijm.*f0_ijm;Sm0_ijp = Dmm_ijp.*(f0_ijpp - f0_ij).*sqrt(lmmhu2p)./pn./dmhup...        - Dmp_ijp./(dpnm + dpnp).*(f0_ippjp-f0_immjp)...        + Fm_ijp.*f0_ijp;